<div id="layer-organizador-apps" class="app-layer hidden flex-col p-4 h-[100dvh] w-full overflow-hidden bg-[#060913]">
    <div class="shrink-0 mb-4">
    <div class="flex items-center justify-between"><div class="flex items-center gap-3"><button onclick="volverAlLauncher()" class="w-10 h-10 rounded-xl bg-white/5 text-gray-300" aria-label="Volver al menú"><i class="fa-solid fa-arrow-left"></i></button><div><h2 class="text-[17px] font-black uppercase text-white">Organizar Apps</h2><p class="text-[8px] text-fuchsia-300 tracking-widest">CARPETAS Y VISIBILIDAD XMB</p></div></div><button onclick="organizadorCargar()" class="w-10 h-10 rounded-xl bg-fuchsia-500/10 border border-fuchsia-500/20 text-fuchsia-300" aria-label="Actualizar"><i class="fa-solid fa-rotate-right"></i></button></div>
    <label class="mt-3 flex items-center gap-3 rounded-2xl border border-fuchsia-400/20 bg-fuchsia-400/[.06] p-3"><span id="organizador-profile-avatar" class="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-fuchsia-400/15 text-fuchsia-100"><i class="fa-solid fa-user"></i></span><span class="min-w-0 flex-1"><small class="block text-[8px] uppercase tracking-widest text-fuchsia-200">Perfil activo de PS4</small><select id="organizador-profile" aria-label="Perfil PS4" class="mt-1 w-full rounded-lg border border-white/10 bg-black/30 px-2 py-2 text-[10px] font-bold text-white"><option value="0">Cargando perfiles…</option></select></span></label>
  </div>
  <div id="organizador-toast" role="status" aria-live="assertive" class="pointer-events-none fixed left-1/2 top-16 z-[200] hidden w-[min(92vw,420px)] -translate-x-1/2 rounded-2xl border border-emerald-400/25 bg-[#101827]/95 px-4 py-3 text-center text-[11px] font-bold text-emerald-100 shadow-2xl backdrop-blur"></div>
  <div class="flex-1 overflow-y-auto hide-scrollbar flex flex-col gap-4 pb-6">
    <div class="rounded-2xl border border-amber-500/25 bg-amber-500/5 p-4"><div class="flex items-start justify-between gap-2"><p class="text-[10px] leading-relaxed text-amber-100"><b>Respaldo de la base de datos XMB</b><br>Se guarda una copia local de <code>app.db</code>. Cada guardado de cambios crea otra copia automáticamente. Cierra juegos y evita apagar la consola durante la operación.</p><button onclick="organizadorActualizar()" class="shrink-0 rounded-xl bg-white/5 px-3 py-2 text-[9px] text-sky-200"><i class="fa-solid fa-rotate"></i> Actualizar apps</button></div><div class="mt-3 grid grid-cols-1 gap-2 sm:grid-cols-2"><button onclick="organizadorRespaldar()" class="rounded-xl bg-white/5 py-2 text-[9px] text-emerald-200"><i class="fa-solid fa-download"></i> Guardar copia actual</button><div class="flex gap-2"><select id="organizador-backup-select" aria-label="Seleccionar respaldo para restaurar" class="min-w-0 flex-1 rounded-xl border border-white/10 bg-black/30 px-2 py-2 text-[8px] text-white"><option value="">Cargando respaldos…</option></select><button id="organizador-restore-btn" onclick="organizadorRestaurar()" class="rounded-xl bg-white/5 px-3 text-[9px] text-amber-200"><i class="fa-solid fa-rotate-left"></i> Restaurar</button></div></div></div>
    <div class="grid grid-cols-2 gap-2 rounded-2xl border border-white/5 bg-[#0a0f1a] p-2"><button id="organizador-tab-folders" onclick="organizadorCambiarVista('folders')" class="rounded-xl bg-fuchsia-400 py-3 text-[10px] font-black uppercase text-black"><i class="fa-solid fa-folder-tree mr-1"></i> Carpetas</button><button id="organizador-tab-hidden" onclick="organizadorCambiarVista('hidden')" class="rounded-xl bg-white/5 py-3 text-[10px] font-black uppercase text-gray-300"><i class="fa-solid fa-eye-slash mr-1"></i> Ocultas <span id="organizador-hidden-count"></span></button></div>
    <section id="organizador-view-folders" class="flex flex-col gap-3">
      <div class="rounded-2xl border border-fuchsia-500/15 bg-[#0a0f1a] p-3"><div class="flex items-center gap-2"><i class="fa-solid fa-folder-plus text-fuchsia-300"></i><input id="organizador-new-folder" maxlength="24" placeholder="Nombre de la carpeta nueva" class="min-w-0 flex-1 rounded-xl border border-white/10 bg-black/30 px-3 py-2 text-[10px] text-white"><button onclick="organizadorCrearCarpeta()" class="rounded-xl bg-fuchsia-500/15 px-3 py-2 text-[9px] font-bold text-fuchsia-200"><i class="fa-solid fa-plus"></i> Crear</button></div></div>
      <div class="rounded-2xl border border-white/5 bg-[#0a0f1a] p-4"><div class="flex items-center justify-between gap-2"><div><h3 class="text-[11px] font-black uppercase text-white">Tus carpetas</h3><p class="mt-1 text-[8px] text-gray-500">Toca una para ver su contenido y asignar apps.</p></div><input id="organizador-app-search" oninput="organizadorRenderApps()" placeholder="Buscar app" class="w-32 rounded-xl border border-white/10 bg-black/30 px-2 py-2 text-[9px] text-white"></div><div id="organizador-folder-list" class="mt-3 grid grid-cols-1 gap-2 sm:grid-cols-2"></div><div id="organizador-unfoldered" class="mt-2"></div></div>
    </section>
    <section id="organizador-view-hidden" class="hidden flex-col gap-3">
      <div class="rounded-2xl border border-rose-500/15 bg-[#0a0f1a] p-4"><h3 class="text-[11px] font-black uppercase text-rose-200"><i class="fa-solid fa-eye-slash mr-1"></i> Ocultas <span id="organizador-hidden-heading"></span></h3><p class="mt-1 text-[8px] text-gray-500">Cambia la casilla para mostrar u ocultar; usa el selector para cambiar de carpeta.</p><div id="organizador-hidden-list" class="mt-3 grid grid-cols-1 gap-2 sm:grid-cols-2"></div></div>
      <details class="rounded-2xl border border-white/5 bg-[#0a0f1a] p-4"><summary class="cursor-pointer text-[10px] font-bold text-gray-300">Apps visibles · organizar o cambiar visibilidad</summary><div id="organizador-visible-list" class="mt-3 grid grid-cols-1 gap-2 sm:grid-cols-2"></div></details>
    </section>
    <button id="organizador-apply" onclick="organizadorAplicar()" class="w-full rounded-xl bg-fuchsia-400 py-3 text-[10px] font-black uppercase text-black disabled:opacity-50" disabled><i class="fa-solid fa-floppy-disk"></i> Guardar cambios en PS4</button>
    <p id="organizador-status" role="status" aria-live="polite" class="whitespace-pre-line rounded-xl border border-white/5 bg-white/[0.03] p-3 text-center text-[9px] text-gray-400">Los cambios se confirman después de verificar la copia en PS4.</p>
    <section class="rounded-2xl border border-white/5 bg-[#0a0f1a] p-4"><div class="flex items-center justify-between gap-2 border-b border-white/5 pb-2"><div><h3 class="text-[10px] font-black uppercase text-white"><i class="fa-solid fa-box-archive mr-1 text-amber-300"></i> Respaldos guardados</h3><p class="mt-1 text-[8px] text-gray-400">Selecciona copias para eliminarlas. Las etiquetas distinguen la más nueva y la más antigua.</p></div><span id="organizador-backup-state" class="text-right text-[8px] text-gray-400"></span></div><div id="organizador-backup-list" class="mt-3 flex max-h-64 flex-col gap-1 overflow-y-auto"></div><div class="mt-3 flex justify-end border-t border-white/5 pt-3"><button id="organizador-delete-backups" onclick="organizadorEliminarRespaldos()" disabled class="shrink-0 rounded-lg bg-rose-500/10 px-3 py-2 text-[8px] font-bold text-rose-200 disabled:opacity-40"><i class="fa-solid fa-trash"></i> Eliminar selección</button></div></section>
  </div>
</div>


